import { useState } from 'react';
import { createEvent } from '../api/eventApi';

const EventForm = () => {
    const [formData, setFormData] = useState({
        name: '', date: '', location: '', maxAttendees: '', description: ''
    });

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        await createEvent(formData);
        window.location.reload();
    };

    return (
        <form onSubmit={handleSubmit} className="event-form">
            <input type="text" name="name" placeholder="Event Name" onChange={handleChange} required />
            <input type="date" name="date" onChange={handleChange} required />
            <input type="text" name="location" placeholder="Location" onChange={handleChange} required />
            <input type="number" name="maxAttendees" placeholder="Max Attendees" onChange={handleChange} required />
            <textarea name="description" placeholder="Description" onChange={handleChange} required />
            <button type="submit">Create Event</button>
        </form>
    );
};

export default EventForm;
